  },
  'undici - pipeline' () {
    return makeParallelRequests(resolve => {
      pipeline(
        new Readable({
          read () {
            this.push(data)
            this.push(null)
          }
        }),
        dispatcher.pipeline(undiciOptions, ({ body }) => {
